// ═══════════════════════════════════════════════════════════════
// WORKFLOW UNIFICADO v3.2 - Estados Unificados (Estilo StatusGator)
// ═══════════════════════════════════════════════════════════════
// Estados unificados: operational, minor, major, critical, maintenance
// Estos estados se usan tanto para servicios propios como StatusGator
// ═══════════════════════════════════════════════════════════════

const webhookData = $('Webhook').first().json.body;

// ─────────────────────────────────────────────────────────────────
// CONFIGURACIÓN DE ESTADOS UNIFICADOS
// ─────────────────────────────────────────────────────────────────
const UNIFIED_STATES = {
  operational: { type: 'up', label: 'Operacional', emoji: '🟢' },
  minor: { type: 'degraded', label: 'Incidencia Menor', emoji: '🟡' },
  major: { type: 'down', label: 'Incidencia Mayor', emoji: '🟠' },
  critical: { type: 'down', label: 'Crítico', emoji: '🔴' },
  maintenance: { type: 'maintenance', label: 'Mantenimiento', emoji: '🔵' }
};

// ─────────────────────────────────────────────────────────────────
// 1. DETECTAR ORIGEN Y NORMALIZAR
// ─────────────────────────────────────────────────────────────────
let normalized = {};

const isStatusGator = webhookData.service && typeof webhookData.service === 'object';

if (isStatusGator) {
  // ═══ STATUSGATOR ═══
  const svc = webhookData.service || {};
  const incident = webhookData.incident || {};

  // StatusGator ya usa: operational, minor, major, critical, maintenance
  const gatorStatus = (svc.current_status || 'operational').toLowerCase();
  const state = UNIFIED_STATES[gatorStatus] || UNIFIED_STATES['operational'];

  normalized = {
    source: 'statusgator',
    service_name: `[SG] ${svc.name || 'Servicio Desconocido'}`,
    service_name_raw: svc.name || 'Servicio Desconocido',
    status: gatorStatus,
    status_type: state.type,
    status_label: state.label,
    status_emoji: state.emoji,
    url: svc.url || incident.url || '',
    timestamp: webhookData.timestamp || new Date().toISOString(),
    incident_title: incident.title || null,
    incident_status: incident.status || null,
    incident_url: incident.url || null,
    raw_code: svc.current_status || 'operational'
  };
} else {
  // ═══ MONITOR PROPIO ═══
  const serviceName = webhookData.service || webhookData.site || 'Servicio Desconocido';
  const errorCode = String(webhookData.error_code || '000').trim();

  // Mapear códigos HTTP a estados unificados (estilo StatusGator)
  let unifiedStatus = 'critical';

  if (errorCode === '200' || errorCode === '302' || errorCode === '301' || errorCode === '204' || errorCode === '304') {
    unifiedStatus = 'operational';
  } else if (errorCode === '000') {
    unifiedStatus = 'critical'; // Sin conexión
  } else if (errorCode.startsWith('5')) {
    if (errorCode === '503' || errorCode === '502') {
      unifiedStatus = 'major'; // Servicio no disponible
    } else {
      unifiedStatus = 'critical'; // Otros errores 5xx
    }
  } else if (errorCode.startsWith('4')) {
    if (errorCode === '408' || errorCode === '429') {
      unifiedStatus = 'minor'; // Timeout o rate limit
    } else {
      unifiedStatus = 'minor'; // Otros errores 4xx
    }
  }

  const state = UNIFIED_STATES[unifiedStatus];

  normalized = {
    source: 'internal',
    service_name: serviceName,
    service_name_raw: serviceName,
    status: unifiedStatus,
    status_type: state.type,
    status_label: state.label,
    status_emoji: state.emoji,
    url: webhookData.site || '',
    timestamp: webhookData.timestamp || new Date().toISOString(),
    incident_title: null,
    incident_status: null,
    incident_url: null,
    raw_code: errorCode
  };
}

// ─────────────────────────────────────────────────────────────────
// 2. LEER ESTADOS ANTERIORES
// ─────────────────────────────────────────────────────────────────
let allStates = {};
let oldStatus = 'first_check';
let oldType = null;

const binaryData = $input.first().binary;
if (binaryData && binaryData.data) {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    const jsonContent = buffer.toString('utf8').trim();
    if (jsonContent && jsonContent !== '{}') {
      allStates = JSON.parse(jsonContent);
    }
    if (allStates[normalized.service_name]) {
      oldStatus = allStates[normalized.service_name].current || 'first_check';
      oldType = allStates[normalized.service_name].current_type || null;
    }
  } catch (error) {
    console.log('Error leyendo JSON:', error);
  }
}

// ─────────────────────────────────────────────────────────────────
// 3. DETECTAR CAMBIO
// ─────────────────────────────────────────────────────────────────
const hasChanged = (normalized.status !== oldStatus);
const isRecovery = hasChanged && normalized.status === 'operational' && oldStatus !== 'operational';
const isDown = hasChanged && (normalized.status === 'major' || normalized.status === 'critical');
const isDegraded = hasChanged && normalized.status === 'minor';
const isMaintenance = hasChanged && normalized.status === 'maintenance';

// StatusGator ya filtra - solo envía webhooks cuando hay incidentes
const shouldAlert = isStatusGator ? true : hasChanged;

// ─────────────────────────────────────────────────────────────────
// 4. ACTUALIZAR ESTADOS
// ─────────────────────────────────────────────────────────────────
if (!allStates[normalized.service_name]) {
  allStates[normalized.service_name] = {
    source: normalized.source,
    current: normalized.status,
    current_type: normalized.status_type,
    previous: null,
    previous_type: null,
    last_change: normalized.timestamp,
    history: []
  };
} else {
  if (hasChanged) {
    allStates[normalized.service_name].history.push({
      from: oldStatus,
      from_type: oldType,
      to: normalized.status,
      to_type: normalized.status_type,
      timestamp: normalized.timestamp
    });
    if (allStates[normalized.service_name].history.length > 50) {
      allStates[normalized.service_name].history.shift();
    }
    allStates[normalized.service_name].last_change = normalized.timestamp;
  }
  allStates[normalized.service_name].previous = oldStatus;
  allStates[normalized.service_name].previous_type = oldType;
  allStates[normalized.service_name].current = normalized.status;
  allStates[normalized.service_name].current_type = normalized.status_type;
  allStates[normalized.service_name].source = normalized.source;
}

// ─────────────────────────────────────────────────────────────────
// 5. RETORNAR DATOS NORMALIZADOS
// ─────────────────────────────────────────────────────────────────
return {
  json: {
    // Control de flujo
    alert: shouldAlert,

    // Datos normalizados
    source: normalized.source,
    service: normalized.service_name,
    service_raw: normalized.service_name_raw,
    url: normalized.url,

    // Estados unificados
    status: normalized.status,
    status_label: normalized.status_label,
    status_emoji: normalized.status_emoji,
    status_type: normalized.status_type,
    raw_code: normalized.raw_code,

    old_status: oldStatus,
    old_status_label: UNIFIED_STATES[oldStatus]?.label || 'Primer Chequeo',
    old_status_type: oldType,

    // Clasificación
    is_recovery: isRecovery,
    is_down: isDown,
    is_degraded: isDegraded,
    is_maintenance: isMaintenance,

    // Incidente (solo StatusGator)
    incident_title: normalized.incident_title,
    incident_status: normalized.incident_status,
    incident_url: normalized.incident_url,

    // Metadata
    timestamp: normalized.timestamp,
    all_states: allStates,
    json_to_save: JSON.stringify(allStates, null, 2)
  }
};

